/* MSC Nastran 2020 SP1; all sample Bulk records are small-field, 80 columns. */
(() => {
 'use strict';
 const empty='この位置は使わない欄です。8文字分を空白のまま残し、右の値を左へ詰めません。0を書く欄ではありません。';
 const next='次の行へ続けるための目印です。この例では+から始まる短い名前を入れ、次の行の第1欄にも同じ名前を書きます。続きがない最後の行では空欄にします。';
 const prev='前の行からの続きを表す目印です。前の行の第10欄と同じ名前を書きます。新しいカード名ではありません。';
 const row=(labels,help)=>labels.map((label,i)=>({label,help:help[label]||(label==='未使用'?empty:label==='次行'?next:label==='継続'?prev:label==='カード名'?'読むデータの種類を指定する名前です。半角英字で左端から書きます。省略できません。':null)}));
 const cards={};
 const add=(name,title,page,intro,labels,help,more=[])=>{cards[name]={name,title,page,intro,lines:[row(labels,help),...more.map(x=>row(x.labels,x.help))]};};
 const head=['カード名'],tail=['次行'];
 add('GRID','節点の場所と座標系',2151,'この模型は節点1だけを使います。CPは「位置を書く軸」、CDは「動きや荷重の成分を読む軸」です。座標の図解と合わせて読みましょう。', [...head,'ID','CP','X1','X2','X3','CD','PS','SEID',...tail],{
 ID:'節点の番号です。この例は1。CONM2やSPC1、DAREAなどが、この番号を使って同じ点を指定します。正の整数を必ず書きます。',
 CP:'X1〜X3をどの座標系で表すかを選ぶ番号です。0は基本座標系。この例は0を明示します。空欄ではGRDSETの指定を引き継ぎ、そこにも指定がなければ0になります。',
 X1:'CPの座標系での第1座標です。この例は直交座標のXで0 mm。空欄の既定値は0です。円筒座標などでは成分の意味が変わります。',
 X2:'CPの座標系での第2座標です。この例はYで0 mm。空欄の既定値は0です。X1が空欄でも位置を詰めません。',
 X3:'CPの座標系での第3座標です。この例はZで0 mm。空欄の既定値は0です。',
 CD:'変位・拘束・力などの成分を表す座標系の番号です。この例は0を明示し、自由度1を基本座標のX方向にします。空欄ではGRDSET、なければ0です。',
 PS:'この節点で常に止める自由度の番号を並べる欄です。例えば23456なら、X方向以外を止めます。この例はSPC1で拘束するため空欄です。GRDSETも使わないので、ここでは追加の拘束は付きません。',
 SEID:'スーパーエレメントという、大きな模型を部分ごとに扱う機能の番号です。今回は使わず空欄。GRDSETの指定もないので通常の残余構造を表す0です。単なる部品名ではありません。'
 });
 add('CELAS2','剛性を直接書くばね',1541,'2つの自由度の間にばねを置きます。線を描いた長さから剛性が決まるのではなく、Kへ書いた値で決まります。', [...head,'EID','K','G1','C1','G2','C2','GE','S',...tail],{
 EID:'要素の番号です。この例は100。別の要素と重ねない正の整数を必ず書きます。',
 K:'ばねの硬さです。この並進ばねは100. N/mm。変位差1 mmに対して100 Nの力を生じます。この例では必ず実数で指定します。',
 G1:'ばねの一方がつながる節点番号。この例はGRID 1です。',C1:'G1のどの動きにばねを効かせるか。1はX並進、2・3はY・Z並進、4〜6は回転です。この例は1。GRIDを使うときは方向を明示します。',
 G2:'反対側の節点番号。0または空欄なら地面（動かない基準）へつながります。この例は0で、別の固定節点を作りません。',
 C2:'G2側の自由度です。この例は地面なので0。実在するGRIDへつなぐなら、その点の1〜6のどの方向かを指定します。',
 GE:'構造減衰の係数です。減衰比ζそのものではありません。空欄の既定は0。この例はTABDMP1で減衰を与えるので空欄とし、重ねて加えません。',
 S:'ばね変形から便宜的な応力を計算する係数です。空欄は0。この例は部材の断面を定義していないので空欄にし、材料応力を評価しません。ばね力と変位を学ぶ模型です。'
 });
 add('CONM2','節点に集める質量',1600,'この例では質量10 kgを1つの節点へ集めます。N・mm・sなので、入力は0.01 tonneです。重さの力Nを入れる欄ではありません。', [...head,'EID','G','CID','M','X1','X2','X3','未使用',...tail],{
 EID:'質量要素の番号です。この例は200。ばねのEID=100とは別にします。正の整数を必ず書きます。',G:'質量を取り付けるGRIDの番号。この例は1で、省略しません。',
 CID:'重心のずれX1〜X3と慣性を表す座標系です。空欄の既定は0（基本座標系）。この例は0を明示します。特別な-1ではX1〜X3が重心の絶対位置になるため、0と同じ意味ではありません。',
 M:'集中質量です。この例は0.01 tonne。空欄の既定は0なので、入れ忘れるとこの質量がなくなります。',
 X1:'節点から重心までのX方向のずれ。この例のCID=0ではmmで、0.を入れて節点と重心を一致させます。空欄は0。',X2:'節点から重心までのY方向のずれ。0.でずれなし。空欄は0。',X3:'節点から重心までのZ方向のずれ。0.でずれなし。空欄は0。'
 },[{labels:['継続','I11','I21','I22','I31','I32','I33','未使用','未使用','次行'],help:Object.fromEntries(['I11','I21','I22','I31','I32','I33'].map(k=>[k,({I11:'重心を通る1軸回りの回転慣性。',I22:'重心を通る2軸回りの回転慣性。',I33:'重心を通る3軸回りの回転慣性。',I21:'1軸と2軸の慣性乗積。',I31:'1軸と3軸の慣性乗積。',I32:'2軸と3軸の慣性乗積。'}[k])+'回転のしにくさを決める量で、単位はtonne·mm²です。空欄は0。この例は回転を拘束するため、継続行全体を省略します。慣性乗積の符号規約は原典の慣性行列を確認します。']))}]);
 add('SPC1','動かさない自由度のセット',3158,'この例はY・Z並進と3つの回転を止め、X並進だけ残します。SPC1のSIDとCase ControlのSPCの値をそろえます。', [...head,'SID','C','G1','G2','G3','G4','G5','G6',...tail],{
 SID:'拘束セットの番号です。この例は10。Case ControlのSPC = 10で、このセットを使います。',C:'止める自由度を並べます。この例は23456。123456なら全部を止め、今回のX振動もできなくなります。省略しません。',
 ...Object.fromEntries([1,2,3,4,5,6].map(n=>['G'+n,n===1?'拘束する節点番号です。この例は1。ここに書いた点のCで選んだ動きを0にします。':'同じ拘束をかけたい追加の節点番号です。この例は1点だけなので空欄。不要な0の節点を追加する意味ではありません。']))
 });
 add('EIGRL','Lanczos法による実固有値計算',1959,'どの固有モードを探すかを指定します。励振する周波数の一覧ではありません。それはFREQ1で指定します。20自由度未満では既定でAHOU法へ自動切替されるため、この1自由度例でAHOUと表示されても入力の誤りではありません（QRG PDF 1962）。', [...head,'SID','V1','V2','ND','MSGLVL','MAXSET','SHFSCL','NORM',...tail],{
 SID:'計算条件の番号。この例は30。Case ControlのMETHOD = 30から選びます。',
 V1:'探す固有振動数の下限Hz。この例は0.。空欄時の探索方法はV2とNDとの組合せで変わるので、この入門では明示します。0を下限にすると負の固有値は探索されず、計算誤差で微小な負になった剛体モードも除外されます。一般模型の診断では、空欄や適切な負の下限を使うことも検討します（QRG PDF 1961）。',
 V2:'探す固有振動数の上限Hz。この例は100.。空欄時はNDなどと組み合わせた探索になります。荷重の最大周波数そのものを入れる欄ではありません。',
 ND:'探す固有値（モード）の数です。この例は1。V1・V2も書いた場合は、その範囲で低い方からND個まで求めます。空欄では範囲などに応じた指定になります。3欄の組合せの詳細は原典参照。',
 MSGLVL:'計算の進み具合について、どれくらい詳しい診断を出すか。空欄の既定は0。この例も空欄。剛性や質量を変える数字ではありません。',
 MAXSET:'Lanczos法の内部計算で使うベクトルのまとまりの上限です。空欄でプログラムの既定に任せます（既定値は計算環境に依存）。求めたいモード数NDとは違います。',
 SHFSCL:'最初の弾性固有振動数を予想して計算を助ける値Hzです。この例は空欄で自動選択に任せます。ここへ値を書いても構造の固有振動数をその値に設定するわけではありません。',
 NORM:'モード形状の大きさをそろえる規則。MASSは一般化質量が1になるようにします。通常の実固有値解析では空欄もMASSが既定。この例は明示します。得られる変位成分は実際の荷重応答のmmではありません。'
 });
 add('PARAM','計算・出力のパラメータ',1007,'同じカード名でも、Nに書く設定名によってV1・V2の意味が変わります。POSTとKDAMPは別々の行で指定します。', [...head,'N','V1','V2','未使用','未使用','未使用','未使用','未使用',...tail],{
 N:'パラメータ名。この例のPOSTは結果ファイルの出力、KDAMPはモード減衰の扱いです。空欄にはできません。',V1:'設定する値。POSTでは-1で従来形式のOP2出力を指定します。KDAMPでは1で粘性モード減衰として扱います。KDAMPの既定も1です。空欄時の意味は設定ごとに違うため、この例では必ず書きます。',V2:'第2の値を取る設定で使います。今回のPOSTとKDAMPはV1だけなので空欄です。0を詰めたり、次のPARAMを同じ行へ入れたりしません。'
 });
 add('DAREA','動荷重の場所・方向・大きさ',1739,'「どこへ、どの方向に、何倍か」を指定します。周波数や時間による変化はRLOAD1/TLOAD1で別に決めます。', [...head,'SID','P1','C1','A1','P2','C2','A2','未使用',...tail],{
 SID:'荷重分布の番号。この例は20。RLOAD1またはTLOAD1のEXCITEIDから呼び出します。',P1:'力をかける節点番号。この例はGRID 1。',C1:'その節点の方向番号。この例は1で、CD=0なので基本座標の＋X方向です。',A1:'荷重の倍率です。この例は後ろの変化関数を無次元としたので100. N。RLOAD/TLOADとDLOADの係数を掛けた結果が最終的な力になります。',P2:'2つ目の荷重点を同じ行へ書くときの節点番号。今回は使わないので空欄です。',C2:'P2の方向。P2を使わない今回も空欄です。C1の繰り返しとして自動で使われる欄ではありません。',A2:'P2の倍率。2つ目の点を定義しない今回は空欄です。'
 });
 add('RLOAD1','周波数で変わる複素荷重',3063,'実部と虚部で、各周波数の荷重を指定します。この例は実部が一定1、虚部0で、100 Nの同じ振幅を与えます。', [...head,'SID','EXCITEID','DELAY','DPHASE','TC/RC','TD/RD','TYPE','未使用',...tail],{
 SID:'動荷重の番号。この例は40。DLOADのL1から呼び出します。',EXCITEID:'荷重の場所と倍率を定義した番号。この例はDAREAのSID=20です。',DELAY:'荷重を時間的に遅らせる指定。実数なら遅れ時間s、正の整数ならDELAYカードの番号です。空欄の既定は遅れなし0。この例は空欄です。',DPHASE:'位相のずれの指定。実数なら角度（度）、正の整数ならDPHASEカードの番号です。空欄は0°で、この例も空欄です。',
 'TC/RC':'実部の周波数変化を与えます。正の整数ならTABLEDiの番号、実数なら一定値。この例の1.0は定数1です。1と書くと表番号1として読まれるので小数点が重要です。空欄は実部0。',
 'TD/RD':'虚部の周波数変化を与えます。正の整数ならTABLEDiの番号、実数なら一定値。この例は0.0で虚部なし。空欄の既定も0です。',TYPE:'励振の種類。LOAD（または0）は力の入力で、この例はLOAD。空欄もLOADが既定です。DISP/VELO/ACCEは強制運動用で、単純にこの欄だけ変えて同じ模型に使うものではありません。'
 });
 add('DLOAD','動荷重を選び、倍率を掛け合わせる',1759,'Case ControlのDLOAD = 50から、このカードのSID=50を選びます。荷重の実体はL1などが呼び出すRLOAD1/TLOAD1です。', [...head,'SID','S','S1','L1','S2','L2','S3','L3',...tail],{
 SID:'動荷重の組合せセット番号。この例は50。Case Controlと一致させます。',S:'全体に掛ける倍率。この例は1.0。ここは省略せず書きます。',S1:'1つ目の動荷重に掛ける倍率。この例は1.0。全体S×個別S1×呼び出す荷重の値で決まります。',L1:'1つ目のRLOAD1/TLOAD1などのSID。この例は40。DAREAのSID=20を直接入れる欄ではありません。',S2:'2つ目の動荷重の倍率。今回は1つだけなので空欄。',L2:'2つ目の動荷重のSID。S2と一緒に使います。今回は空欄。',S3:'3つ目の動荷重の倍率。今回は空欄。',L3:'3つ目の動荷重のSID。S3と一緒に使います。今回は空欄。'
 },[{labels:['継続','S4','L4','S5','L5','S6','L6','S7','L7','次行'],help:Object.fromEntries([4,5,6,7].flatMap(n=>[['S'+n,n+'個目の動荷重に掛ける倍率。必要な追加荷重だけ、対応するL'+n+'と組にして書きます。今回この継続行は使いません。'],['L'+n,n+'個目の動荷重のSID。S'+n+'と組です。組を追加しない部分は両方空欄。必要なら同じ形でさらに継続できます。']]))}]);
 add('FREQ1','等間隔の計算周波数',2041,'応答を計算する周波数の一覧を作ります。固有振動数を探す範囲EIGRLとは違う指定です。', [...head,'SID','F1','DF','NDF','未使用','未使用','未使用','未使用',...tail],{
 SID:'周波数セットの番号。この例は60。Case ControlのFREQUENCY = 60で選びます。',F1:'最初の周波数Hz。この例は0.0。0 Hzは静的な極限を確かめる点で、振動を1秒に0回繰り返す状態に対応します。',DF:'次の計算点までの間隔Hz。この例は0.1。空欄にせず正の値を指定します。ピークを飛ばさない細かさを考えます。',NDF:'F1にDFを何回足すか。400なら0+0.1×400=40 Hzまでです。最初の点もあるので計算点は401個。空欄の既定は1ですが、この例は400を明示します。'
 });
 add('TABDMP1','モードの減衰を振動数ごとに指定',3213,'モードの固有振動数から減衰を読み取る表です。SDAMPING = 70で選択します。加振周波数ごとの力の表ではありません。', [...head,'TID','TYPE','未使用','未使用','未使用','未使用','未使用','未使用',...tail],{
 TID:'減衰表の番号。この例は70。Case ControlのSDAMPINGとそろえます。',TYPE:'値の表し方。CRITは臨界減衰に対する比ζ、Gは構造減衰係数、QはQ値です。空欄の既定はGなので、今回の0.02を2%として使うためCRITを必ず書きます。'
 },[{labels:['継続','f1','g1','f2','g2','ENDT','未使用','未使用','未使用','次行'],help:{f1:'1組目の固有振動数Hz。この例は0.0。対応する減衰g1と組にします。',g1:'f1での減衰値。TYPE=CRITなので0.02は2%。2.0なら200%になってしまいます。',f2:'2組目の固有振動数Hz。この例は100.0。間は直線で補間されます。',g2:'f2での減衰値。この例も0.02なので、2点の間のどの固有振動数でも2%になります。',ENDT:'表のデータがここで終わるという印です。最後のfとgの組の次のデータ欄にENDTを書きます。空欄で省略しません。追加の組を書くと、この印の位置も後ろへ移ります。'}}]);
 add('TLOAD1','時間で変わる荷重',3299,'荷重の時間変化を、TABLED1などの表から読みます。今回の表は無次元の倍率で、DAREAの100 Nと掛け合わせます。', [...head,'SID','EXCITEID','DELAY','TYPE','TID/F','US0','VS0','未使用',...tail],{
 SID:'動荷重の番号。この例は40で、DLOADのL1から呼び出します。',EXCITEID:'荷重の分布番号。この例はDAREAの20で、節点1のX方向を選びます。',DELAY:'荷重を遅らせる指定。実数なら秒、正の整数ならDELAYカードの番号です。空欄の既定は0で遅れなし。この例は空欄です。',TYPE:'励振の種類。この例は力なのでLOAD。空欄の既定もLOADです。強制変位・速度・加速度の種類とは入力の組立てが変わります。',
 'TID/F':'正の整数はTABLEDiの番号、実数は一定値です。この例は表番号80なので80と書きます。80.0と書くと一定80の関数になり、時間波形の表を読まなくなります。省略しません。',
 US0:'強制運動を与えるときの初期変位の倍率です。模型全体の自由振動の初期変位をここで設定するわけではありません。今回のTYPE=LOADでは使わず空欄。既定は0。一般の初期状態は別のIC/TIC機能です。',VS0:'強制運動を与えるときの初期速度の倍率です。今回の力入力では使わず空欄。既定は0。おもりの初期速度をこの欄へ直接入れる、と解釈しません。'
 });
 add('TABLED1','時間や周波数の変化を点の組で指定',3222,'この例は横軸が時刻s、縦軸が荷重の倍率です。横軸の意味や単位は、この表を使うカードによって変わります。MSC 2020 SP1の書式です。', [...head,'TID','XAXIS','YAXIS','未使用','未使用','未使用','未使用','未使用',...tail],{
 TID:'表の番号。この例は80。TLOAD1のTID/Fに整数80を書いて、この表を呼び出します。',XAXIS:'横軸を直線目盛LINEARまたは対数目盛LOGで扱う指定。この例は時刻0を含むのでLINEAR。空欄の既定もLINEARです。',YAXIS:'縦軸の扱い。この例は0を含む倍率なのでLINEARです。空欄もLINEARが既定。対数目盛を選ぶには値が正であるなどの条件があり、0のままLOGへ変えません。'
 },[{labels:['継続','x1','y1','x2','y2','x3','y3','x4','y4','次行'],help:Object.fromEntries([1,2,3,4].flatMap(n=>[['x'+n,`${n}組目の時刻。この例は${['0.0','0.02','0.04','1.0'][n-1]} s。隣のy${n}と組にし、時刻順に並べます。`],['y'+n,`${n}組目の荷重倍率。この例は${[0,1,0,0][n-1]}。DAREAの100 Nと掛けて${[0,100,0,0][n-1]} Nになります。4点を直線で結び、最後の2点を0にして、表の後方へ外挿しても力が0になるようにします。`]]))},{labels:['継続','ENDT','未使用','未使用','未使用','未使用','未使用','未使用','未使用','次行'],help:{ENDT:'表の終わりの印です。4組の点が前の行のデータ8欄を使い切るため、次の行の第2欄へENDTを書きます。第10欄は継続の目印用なので、そこへENDTを入れません。'}}]);
 add('TSTEP','時間刻みと出力の間隔',3320,'時間を何回、何秒ずつ進めるかを指定します。Case ControlのTSTEP = 90で選びます。ここでは1つの区間だけ使います。', [...head,'SID','N1','DT1','NO1','未使用','未使用','未使用','未使用',...tail],{
 SID:'時間計算の設定番号。この例は90で、Case Controlと一致させます。',N1:'この区間で進めるステップの数。この例は2000。必須の正の整数です。DT1との積がこの区間の長さになります。',DT1:'1回で進む時間。この例は0.0005 s。必須の正の実数です。細かくすると波形を追いやすくなりますが計算量も増えます。',NO1:'何ステップごとに結果を出すか。この例は1で毎回。空欄の既定も1です。10なら10回ごと。大きくしてもDT1は変わりませんが、出力からピークを見落とすことがあります。'
 },[{labels:['継続','未使用','N2','DT2','NO2','未使用','未使用','未使用','未使用','次行'],help:{N2:'次の時間区間のステップ数です。今回使わないので継続行全体を省略します。使う場合は第3欄から書き、第2欄は空白です。',DT2:'次の区間の時間刻みです。途中で刻みを変える必要があるときに使います。この例は一定の刻みなので不要です。',NO2:'次の区間の出力間隔。指定の意味はNO1と同じです。区間を追加しない場合は、この行を作りません。さらに区間を追加するときも同じ配置です。'}}]);
 function fixed(values){if(values.length>10)throw Error('Too many fields');return Array.from({length:10},(_,i)=>{const v=String(values[i]??'');if(v.length>8||/[^\x20-\x7e]/.test(v))throw Error('Invalid field: '+v);return v.padEnd(8);}).join('');}
 const record=(name,values,line=0)=>({name,line,values,text:fixed(values)});
 const common=[record('GRID',['GRID','1','0','0.','0.','0.','0']),record('CELAS2',['CELAS2','100','100.','1','1','0','0']),record('CONM2',['CONM2','200','1','0','0.01','0.','0.','0.']),record('SPC1',['SPC1','10','23456','1']),record('EIGRL',['EIGRL','30','0.','100.','1','','','','MASS'])];
 const damp=[record('TABDMP1',['TABDMP1','70','CRIT','','','','','','','+D1']),record('TABDMP1',['+D1','0.','0.02','100.','0.02','ENDT'],1)];
 const models={};
 for(const sol of ['103','111','112']){
  const exec=['SOL '+sol,'CEND'];
  const control=['TITLE = SDOF LEARNING SOL '+sol,'ECHO = NONE','SUBCASE 1','  SPC = 10','  METHOD = 30'];
  if(sol==='111')control.push('  DLOAD = 50','  FREQUENCY = 60','  SDAMPING = 70','  DISPLACEMENT(SORT1,PHASE) = ALL','  VELOCITY(SORT1,PHASE) = ALL','  ACCELERATION(SORT1,PHASE) = ALL');
  else if(sol==='112')control.push('  DLOAD = 50','  TSTEP = 90','  SDAMPING = 70','  DISPLACEMENT(SORT1) = ALL','  VELOCITY(SORT1) = ALL','  ACCELERATION(SORT1) = ALL');
  else control.push('  DISPLACEMENT = ALL');
  const rows=[record('PARAM',['PARAM','POST','-1'])];
  if(sol!=='103')rows.push(record('PARAM',['PARAM','KDAMP','1']));
  rows.push(...common);
  if(sol!=='103')rows.push(record('DAREA',['DAREA','20','1','1','100.']),record('DLOAD',['DLOAD','50','1.0','1.0','40']));
  if(sol==='111')rows.push(record('RLOAD1',['RLOAD1','40','20','','','1.0','0.0','LOAD']),record('FREQ1',['FREQ1','60','0.','0.1','400']),...damp);
  if(sol==='112')rows.push(record('TLOAD1',['TLOAD1','40','20','','LOAD','80']),record('TSTEP',['TSTEP','90','2000','0.0005','1']),...damp,record('TABLED1',['TABLED1','80','LINEAR','LINEAR','','','','','','+T1']),record('TABLED1',['+T1','0.','0.','0.02','1.','0.04','0.','1.','0.','+T2'],1),record('TABLED1',['+T2','ENDT'],2));
  models[sol]={exec,control,rows,name:'sdof_sol'+sol+'.bdf',text:[...exec,...control,'BEGIN BULK',...rows.map(r=>r.text),'ENDDATA',''].join('\r\n')};
 }
 for(const card of Object.values(cards))for(const fields of card.lines)if(fields.length!==10||fields.some(f=>!f.help))throw Error('Incomplete field guide: '+card.name);
 const wn=100,fn=wn/(2*Math.PI),mass=.01,k=100,F=100;
 function response(f,z){const r=f/fn;return {amplitude:F/k/Math.hypot(1-r*r,2*z*r),lag:Math.atan2(2*z*r,1-r*r)*180/Math.PI};}
 function force(t){return t<0?0:t<.02?F*t/.02:t<.04?F*(.04-t)/.02:0;}
 function transient(z,dt=.0005,duration=1){const c=2*z*mass*wn,acc=(t,u,v)=>(force(t)-c*v-k*u)/mass;let u=0,v=0;const result=[{t:0,u,v,a:0,f:0}];for(let i=0;i<Math.round(duration/dt);i++){const t=i*dt,a1=acc(t,u,v),v2=v+dt*a1/2,u2=u+dt*v/2,a2=acc(t+dt/2,u2,v2),v3=v+dt*a2/2,u3=u+dt*v2/2,a3=acc(t+dt/2,u3,v3),v4=v+dt*a3,u4=u+dt*v3,a4=acc(t+dt,u4,v4);u+=dt*(v+2*v2+2*v3+v4)/6;v+=dt*(a1+2*a2+2*a3+a4)/6;const end=(i+1)*dt;result.push({t:end,u,v,a:acc(end,u,v),f:force(end)});}return result;}
 window.NastranDynamics={cards,models,fixed,fn,wn,mass,k,F,response,force,transient};
})();
